<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
require dirname(__DIR__,2).'/app/BusinessDestinationTransfer.php';
if(isset($_SESSION['admin'])&&time()-(int)($_SESSION['last_seen']??0)>1800)unset($_SESSION['admin']);
if(empty($_SESSION['admin'])){http_response_code(403);exit('Inicia sesión desde el panel de administración.');}
$_SESSION['last_seen']=time();$error='';$plan=null;$result=$_SESSION['business_destination_transfer']??null;unset($_SESSION['business_destination_transfer']);
try{
    $service=new BusinessDestinationTransfer(db());
    if($_SERVER['REQUEST_METHOD']==='POST'){
        csrf();
        if(($_POST['action']??'')!=='transfer')throw new RuntimeException('Acción no válida.');
        $_SESSION['business_destination_transfer']=$service->apply(is_array($_POST['business_ids']??null)?$_POST['business_ids']:[],(string)($_POST['preview_hash']??''),($_POST['confirm_transfer']??'')==='1',(string)($config['admin_user']??'administrador'),dirname(__DIR__));
        header('Location: trasladar-negocios.php',true,303);exit;
    }
    $plan=$service->preview();
}catch(Throwable $exception){http_response_code(400);$error=$exception instanceof PDOException?'No se aplicó el traslado. Revisa las tablas de destinos, negocios y auditoría (027) en Base de datos.':$exception->getMessage();}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Trasladar negocios a Cauca Viejo | Administración</title><link rel="stylesheet" href="../assets/style.css?v=admin-navigation-20261015"><link rel="stylesheet" href="../assets/admin.css?v=admin-workflow-20261015-4"><?php require __DIR__.'/_theme.php'; ?></head><body class="portal-admin"><main class="wrap admin-page destination-admin"><a class="brand" href="index.php"><span>Explorando<b>Lugares</b></span></a><h1>Trasladar negocios a Cauca Viejo</h1><?php require __DIR__.'/_navigation.php';?><p><a href="destinos.php">← Volver a destinos</a></p>
<?php if($error):?><p class="notice" role="alert"><?=esc($error)?></p><?php endif ?>
<?php if(is_array($result)):?><section class="notice" role="status"><h2><?=count($result['moved'])?> negocios trasladados</h2><p>Se conservaron los ID, canales, categorías, cuentas, suscripciones y estados de las fichas.</p><ul><?php foreach($result['moved'] as $moved):?><li><?=esc($moved['name'])?> · ID <?=esc($moved['id'])?></li><?php endforeach ?></ul><a href="negocios.php?tab=lista&amp;destino=<?=esc($result['target_id'])?>">Ver negocios en Cauca Viejo</a></section><?php endif ?>
<?php if($plan):?><section class="account-portal-card"><h2>Jericó → Cauca Viejo</h2><p>Este lote contiene fichas existentes identificadas mediante fuentes. Solo cambia su destino. Si Cauca Viejo aún no existe, se creará en borrador.</p><p class="notice"><strong>Visibilidad:</strong> las fichas trasladadas dejarán de aparecer en el directorio de Jericó. Mientras Cauca Viejo siga en borrador, tampoco aparecerán públicamente en ese destino. No se publica el destino ni se modifica el estado de las fichas.</p><p><?=count($plan['ready'])?> disponibles · <?=count($plan['already'])?> ya asociados · <?=count($plan['omitted'])?> pendientes por coincidencia o duplicidad</p>
<?php if($plan['ready']):?><form method="post"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="transfer"><input type="hidden" name="preview_hash" value="<?=esc($plan['hash'])?>"><div class="destination-admin-table"><table><thead><tr><th>Elegir</th><th>Negocio</th><th>Procedencia de la clasificación</th></tr></thead><tbody><?php foreach($plan['ready'] as $business):?><tr><td><input type="checkbox" name="business_ids[]" value="<?=esc($business['id'])?>" checked aria-label="Trasladar <?=esc($business['display_name'])?>"></td><td><strong><?=esc($business['display_name'])?></strong><br><small>ID <?=esc($business['id'])?></small></td><td><?=esc($business['evidence']['note'])?><br><a href="<?=esc($business['evidence']['source_url'])?>" target="_blank" rel="noopener noreferrer">Consultar fuente</a></td></tr><?php endforeach ?></tbody></table></div><p><label><input type="checkbox" name="confirm_transfer" value="1" required> Confirmo trasladar las fichas seleccionadas y he revisado su ubicación y el efecto sobre su visibilidad.</label></p><button class="pill compact" type="submit">Trasladar los negocios seleccionados a Cauca Viejo</button></form><?php else:?><p>No hay fichas pendientes que puedan trasladarse con este lote.</p><?php endif ?></section>
<?php if($plan['omitted']):?><section><h2>Revisar coincidencias</h2><ul><?php foreach($plan['omitted'] as $item):?><li><strong><?=esc($item['name'])?>:</strong> <?=esc($item['reason'])?></li><?php endforeach ?></ul></section><?php endif ?>
<section><h2>Se conservan en Jericó</h2><ul><?php foreach($plan['excluded'] as $item):?><li><strong><?=esc($item['name'])?>:</strong> <?=esc($item['reason'])?></li><?php endforeach ?></ul><p>La clasificación territorial no acredita que un negocio siga operando ni modifica sus permisos para campañas.</p></section><?php endif ?></main></body></html>
